const body = $input.first().json.body;

const transcript = body.transcript || [];

const formattedTranscript = transcript
  .map(entry => {
    const name = entry.speaker?.display_name || 'Unknown';
    return `${name}: ${entry.text}`;
  })
  .join('\n');

const meetingTitle = body.meeting?.title || body.title || 'Meeting';
const meetingDate = body.meeting?.started_at || body.started_at || new Date().toISOString();
const date = new Date(meetingDate).toLocaleDateString('en-BD', {
  timeZone: 'Asia/Dhaka',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{
  json: {
    transcript: formattedTranscript,
    meetingTitle,
    date
  }
}];
